export const SYSTEM_INSTRUCTION = `
You are Aether Health, a Responsible AI healthcare assistant.
Your goal is to provide calm, accurate, culturally inclusive, and non-alarmist health assistance.
You are NOT a doctor. Never provide definitive medical diagnoses or treatment plans.
Always prioritize harm reduction and safety.
Use probability-based reasoning.
Avoid fear-inducing language.

OUTPUT FORMAT:
You must always return a valid JSON object. Do not wrap it in markdown code blocks.
`;

import { GoogleGenAI } from "@google/genai";
import { ElementType, AnalysisResult } from '../types';
import { SYSTEM_INSTRUCTION } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Schemas for structured output
const fireSchema = {
  type: "OBJECT",
  properties: {
    emotionalState: { type: "STRING" },
    likelyCauses: { 
      type: "ARRAY", 
      items: {
        type: "OBJECT",
        properties: {
          cause: { type: "STRING" },
          probability: { type: "STRING" }
        }
      } 
    },
    whatThisMeans: { type: "STRING" },
    safetyAdvice: { type: "STRING" },
    reassuranceLine: { type: "STRING" },
    reasoningSummary: { type: "STRING" }
  },
  required: ["emotionalState", "likelyCauses", "whatThisMeans", "safetyAdvice", "reassuranceLine", "reasoningSummary"]
};

const earthSchema = {
  type: "OBJECT",
  properties: {
    medicineIdentified: { type: "STRING" },
    authenticityConfidence: { type: "STRING" },
    redFlags: { type: "ARRAY", items: { type: "STRING" } },
    safetyAdvice: { type: "STRING" },
    reassuranceLine: { type: "STRING" },
    reasoningSummary: { type: "STRING" }
  },
  required: ["medicineIdentified", "authenticityConfidence", "safetyAdvice", "reassuranceLine"]
};

const spaceSchema = {
  type: "OBJECT",
  properties: {
    localizedExplanation: { type: "STRING" },
    wellnessSuggestions: { type: "ARRAY", items: { type: "STRING" } },
    culturalNotes: { type: "STRING" },
    reassuranceLine: { type: "STRING" },
    reasoningSummary: { type: "STRING" }
  }
};

const waterSchema = {
  type: "OBJECT",
  properties: {
    waterQualityRisk: { type: "STRING", enum: ["Low", "Moderate", "High"] },
    reportSummary: { type: "STRING" },
    reassuranceLine: { type: "STRING" },
    reasoningSummary: { type: "STRING" },
    safetyAdvice: { type: "STRING" }
  }
};

const airSchema = {
  type: "OBJECT",
  properties: {
    ocrInterpretation: { type: "STRING" },
    ambiguityFlags: { type: "ARRAY", items: { type: "STRING" } },
    safetyAdvice: { type: "STRING" },
    reassuranceLine: { type: "STRING" },
    reasoningSummary: { type: "STRING" }
  }
};

export const generateAetherResponse = async (
  element: ElementType,
  input: string,
  imagePart?: string
): Promise<AnalysisResult> => {

  let modelName = 'gemini-3-flash-preview';
  let systemPrompt = SYSTEM_INSTRUCTION;
  let userPrompt = input;
  let responseSchema: any = {};

  switch (element) {
    case ElementType.FIRE:
      systemPrompt += `
      MODE: FIRE (VitalScan).
      Task: Analyze symptoms to reduce anxiety.
      1. Detect emotional tone (fear, panic, neutral).
      2. Identify likely causes using standard medical reasoning (common cold, tension headache, etc.).
      3. Assign probabilities.
      4. Reassure the user.
      5. State clearly when to seek help.
      `;
      responseSchema = fireSchema;
      break;

    case ElementType.EARTH:
      modelName = 'gemini-2.5-flash-image'; // Better for images
      systemPrompt += `
      MODE: EARTH (TrueMeds).
      Task: Detect potential counterfeit medicine issues from packaging.
      1. Identify drug name if visible.
      2. Check for visual anomalies (typos, bad print quality).
      3. Provide confidence score (High/Med/Low).
      4. Suggest verification steps.
      `;
      userPrompt = "Analyze this image of medicine packaging for authenticity cues.";
      // Note: 2.5-flash-image doesn't support strict schema enforcement in config as robustly as 3-flash, 
      // but we will prompt for JSON.
      break;

    case ElementType.SPACE:
      systemPrompt += `
      MODE: SPACE (LifeLoop).
      Task: Holistic wellbeing and translation.
      1. Explain the concept in a simple, culturally inclusive way.
      2. Suggest non-medical wellness activities (breathing, diet, movement).
      3. Avoid spiritual absolutes.
      `;
      responseSchema = spaceSchema;
      break;

    case ElementType.WATER:
      systemPrompt += `
      MODE: WATER (HydroGuard).
      Task: Simulate an environmental water safety report.
      Generate a realistic but simulated report for a civic water body.
      Risk classification: Low, Moderate, or High.
      `;
      userPrompt = "Generate a simulated civic water safety report.";
      responseSchema = waterSchema;
      break;

    case ElementType.AIR:
      systemPrompt += `
      MODE: AIR (ClearScript).
      Task: Simulate prescription analysis to prevent errors.
      Describe how you would read a prescription safely.
      Flag potential ambiguities.
      Warn against guessing dosages.
      `;
      userPrompt = "Demonstrate safe prescription analysis principles.";
      responseSchema = airSchema;
      break;
  }

  try {
    const config: any = {
      responseMimeType: "application/json",
      systemInstruction: systemPrompt,
    };

    // Only apply schema if supported and defined
    if (element !== ElementType.EARTH && element !== ElementType.AIR && element !== ElementType.WATER) { 
        // Applying schema mostly for text-heavy logic models. 
        // For EARTH (Vision), strict JSON schema sometimes conflicts with vision tasks in some preview models, 
        // so we rely on the system instruction "return valid JSON".
        config.responseSchema = responseSchema;
    }

    let contents: any = userPrompt;

    // Handle Image Input
    if (imagePart && element === ElementType.EARTH) {
      contents = {
        parts: [
          { inlineData: { mimeType: 'image/png', data: imagePart } },
          { text: userPrompt }
        ]
      };
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: contents,
      config: config
    });

    const text = response.text;
    if (!text) throw new Error("No response generated");

    // Clean markdown if present (e.g. ```json ... ```)
    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanedText) as AnalysisResult;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React from 'react';
import { ElementType } from '../types';
import { ELEMENTS } from '../constants';

interface ElementSelectorProps {
  currentElement: ElementType;
  onSelect: (el: ElementType) => void;
}

const ElementSelector: React.FC<ElementSelectorProps> = ({ currentElement, onSelect }) => {
  return (
    <div className="flex flex-wrap justify-center gap-4 mb-8">
      {Object.values(ELEMENTS).map((el) => {
        const Icon = el.icon;
        const isActive = currentElement === el.id;

        return (
          <button
            key={el.id}
            onClick={() => onSelect(el.id)}
            className={`
              flex items-center gap-2 px-6 py-3 rounded-full transition-all duration-300 border
              ${isActive 
                ? `${el.bg} ${el.color} border-${el.id === 'FIRE' ? 'rose' : el.id === 'WATER' ? 'sky' : el.id === 'EARTH' ? 'green' : el.id === 'AIR' ? 'slate' : 'violet'}-200 shadow-md transform scale-105 ring-2 ring-offset-2 ring-transparent` 
                : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'}
            `}
          >
            <Icon className={`w-5 h-5 ${isActive ? el.color : 'text-gray-400'}`} />
            <span className="font-medium">{el.name}</span>
          </button>
        );
      })}
    </div>
  );
};

export default ElementSelector;

