export default TrustPanel;

import React from 'react';
import { AnalysisResult, ElementType } from '../types';
import { ELEMENTS } from '../constants';

interface OutputDisplayProps {
  element: ElementType;
  result: AnalysisResult;
}

const OutputDisplay: React.FC<OutputDisplayProps> = ({ element, result }) => {
  const config = ELEMENTS[element];

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden animate-fade-in">

      {/* Header */}
      <div className={`${config.bg} px-6 py-4 border-b border-gray-100 flex justify-between items-center`}>
        <h2 className={`text-lg font-semibold ${config.color} flex items-center gap-2`}>
          <config.icon className="w-5 h-5" />
          Analysis Complete
        </h2>
        {result.authenticityConfidence && (
           <span className={`px-3 py-1 rounded-full text-sm font-medium ${
             result.authenticityConfidence.toLowerCase().includes('high') ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
           }`}>
             Confidence: {result.authenticityConfidence}
           </span>
        )}
      </div>

      <div className="p-6 space-y-6">

        {/* Fire: Likely Causes */}
        {element === ElementType.FIRE && result.likelyCauses && (
          <div className="space-y-3">
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wide">Possibilities (Not Diagnosis)</h3>
            <div className="grid gap-3">
              {result.likelyCauses.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-3 rounded-lg bg-gray-50 border border-gray-100">
                  <span className="font-medium text-gray-700">{item.cause}</span>
                  <span className="text-sm font-bold text-fire-500">{item.probability}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Earth: Red Flags */}
        {element === ElementType.EARTH && result.medicineIdentified && (
          <div className="space-y-3">
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wide">Visual Inspection</h3>
            <p className="text-gray-700">Identified: <span className="font-semibold">{result.medicineIdentified}</span></p>
             {result.redFlags && result.redFlags.length > 0 ? (
               <ul className="list-disc pl-5 space-y-1 text-red-600 text-sm">
                 {result.redFlags.map((flag, i) => <li key={i}>{flag}</li>)}
               </ul>
             ) : (
               <p className="text-green-600 text-sm flex items-center gap-2">
                 <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                 No immediate red flags detected.
               </p>
             )}
          </div>
        )}

        {/* Space: Localized & Wellness */}
        {element === ElementType.SPACE && (
          <div className="space-y-4">
             <div className="p-4 bg-space-50 rounded-lg border border-space-100 text-space-900">
               {result.localizedExplanation}
             </div>
             <div>
               <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wide mb-2">Holistic Suggestions</h3>
               <div className="flex flex-wrap gap-2">
                 {result.wellnessSuggestions?.map((s, i) => (
                   <span key={i} className="px-3 py-1 bg-white border border-gray-200 rounded-full text-sm text-gray-600">
                     {s}
                   </span>
                 ))}
               </div>
             </div>
             {result.culturalNotes && (
               <p className="text-sm text-gray-500 italic border-l-2 border-space-200 pl-3">
                 {result.culturalNotes}
               </p>
             )}
          </div>
        )}

        {/* Water: Risk Report */}
        {element === ElementType.WATER && (
          <div className="space-y-4">
             <div className="flex items-center gap-3">
               <span className="text-gray-600">Risk Level:</span>
               <span className={`text-lg font-bold ${
                 result.waterQualityRisk === 'High' ? 'text-red-600' : result.waterQualityRisk === 'Moderate' ? 'text-yellow-600' : 'text-green-600'
               }`}>
                 {result.waterQualityRisk}
               </span>
             </div>
             <p className="text-gray-700">{result.reportSummary}</p>
          </div>
        )}

        {/* Air: OCR Interpretation */}
        {element === ElementType.AIR && (
          <div className="space-y-4">
             <div className="p-4 bg-gray-50 rounded border border-gray-200 font-mono text-sm text-gray-700">
                {result.ocrInterpretation}
             </div>
             {result.ambiguityFlags && (
               <div className="bg-yellow-50 p-3 rounded text-sm text-yellow-800">
                 <strong>Ambiguities:</strong> {result.ambiguityFlags.join(', ')}
               </div>
             )}
          </div>
        )}

        {/* Universal Sections */}
        {result.whatThisMeans && (
          <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
            <h3 className="text-blue-800 font-semibold mb-1 text-sm">What this probably means</h3>
            <p className="text-blue-900 text-sm leading-relaxed">{result.whatThisMeans}</p>
          </div>
        )}

        {result.safetyAdvice && (
           <div className="flex gap-3 items-start p-4 bg-gray-50 rounded-lg">
             <div className="p-1 bg-gray-200 rounded-full text-gray-600 mt-0.5">
               <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
               </svg>
             </div>
             <div>
               <h3 className="font-semibold text-gray-700 text-sm mb-1">Safety First</h3>
               <p className="text-sm text-gray-600">{result.safetyAdvice}</p>
             </div>
           </div>
        )}

        <div className="pt-4 border-t border-gray-100 text-center">
           <p className={`text-lg font-medium italic ${config.color}`}>
             "{result.reassuranceLine}"
           </p>
        </div>

      </div>
    </div>
  );
};

export default OutputDisplay;

import React, { useState } from 'react';
import { ElementType, AnalysisResult } from './types';
import { ELEMENTS } from './constants';
import { generateAetherResponse } from './services/geminiService';
import ElementSelector from './components/ElementSelector';
import OutputDisplay from './components/OutputDisplay';
import TrustPanel from './components/TrustPanel';

const App: React.FC = () => {
  const [currentElement, setCurrentElement] = useState<ElementType>(ElementType.FIRE);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const currentConfig = ELEMENTS[currentElement];

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        // Remove data URL prefix for Gemini API
        const base64String = reader.result as string;
        const base64Content = base64String.split(',')[1];
        setSelectedImage(base64Content);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAction = async () => {
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const response = await generateAetherResponse(
        currentElement, 
        inputText, 
        selectedImage || undefined
      );
      setResult(response);
    } catch (err) {
      setError("Unable to connect to Aether's core. Please try again.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const resetState = (el: ElementType) => {
    setCurrentElement(el);
    setResult(null);
    setInputText('');
    setSelectedImage(null);
    setError(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-gray-100 text-gray-800 pb-12">

      {/* Header */}
      <header className="bg-white/80 backdrop-blur-md sticky top-0 z-10 border-b border-gray-200">
        <div className="max-w-5xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
