import React from 'react';

export enum ElementType {
  FIRE = 'FIRE',
  EARTH = 'EARTH',
  WATER = 'WATER',
  AIR = 'AIR',
  SPACE = 'SPACE'
}

export interface ElementConfig {
  id: ElementType;
  name: string;
  tagline: string;
  description: string;

  // Styling
  gradientFrom: string;
  gradientTo: string;
  textAccent: string;
  bg: string;
  color: string;

  icon: React.FC<any>;
  inputType: 'text' | 'image' | 'mock_action';
  placeholder?: string;
}

// Structure for the JSON response from Gemini
export interface AnalysisResult {
  // Fire
  emotionalState?: string;
  likelyCauses?: Array<{ cause: string; probability: string }>;

  // Earth
  medicineIdentified?: string;
  authenticityConfidence?: string;
  redFlags?: string[];

  // Space
  localizedExplanation?: string;
  wellnessSuggestions?: string[];
  culturalNotes?: string;

  // Water
  waterQualityRisk?: 'Low' | 'Moderate' | 'High';
  reportSummary?: string;

  // Air
  ocrInterpretation?: string;
  ambiguityFlags?: string[];

  // Common
  reasoningSummary: string; // For Trust Panel
  safetyAdvice: string; // "When to seek help" or "Safety Advice"
  reassuranceLine: string; // The closing supportive line
  whatThisMeans?: string; // General explanation
}

export type Language = 'en' | 'es' | 'fr' | 'de' | 'zh' | 'ja';
export type Tone = 'calm' | 'neutral' | 'supportive';

export interface UserProfile {
  language: Language;
  tone: Tone;
  accessibility: {
    largeText: boolean;
  };
}

import React from 'react';
import { UserProfile, Language, Tone } from '../types';

interface SettingsPanelProps {
  profile: UserProfile;
  onUpdate: (profile: UserProfile) => void;
  onClose: () => void;
  t: any; // Translations
}

const SettingsPanel: React.FC<SettingsPanelProps> = ({ profile, onUpdate, onClose, t }) => {
  const languages: { code: Language; label: string }[] = [
    { code: 'en', label: 'English' },
    { code: 'es', label: 'Español' },
    { code: 'fr', label: 'Français' },
    { code: 'de', label: 'Deutsch' },
    { code: 'zh', label: '中文' },
    { code: 'ja', label: '日本語' }
  ];

  const tones: { code: Tone; label: string }[] = [
    { code: 'calm', label: 'Calm' },
    { code: 'neutral', label: 'Neutral' },
    { code: 'supportive', label: 'Supportive' }
  ];

  const handleLanguageChange = (code: Language) => {
    onUpdate({ ...profile, language: code });
  };

  const handleToneChange = (code: Tone) => {
    onUpdate({ ...profile, tone: code });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in">
      <div className="w-full max-w-md bg-[#151A25] rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-slide-up">
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-white/5">
          <h2 className="text-xl font-display font-semibold text-white">{t.preferences}</h2>
          <button 
            onClick={onClose}
            className="p-2 rounded-full hover:bg-white/10 text-gray-400 hover:text-white transition-colors"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-8">

          {/* Language */}
          <div className="space-y-3">
            <label className="text-xs font-bold text-gray-500 uppercase tracking-widest">{t.language}</label>
            <div className="grid grid-cols-2 gap-2">
              {languages.map((lang) => (
                <button
                  key={lang.code}
                  onClick={() => handleLanguageChange(lang.code)}
                  className={`px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    profile.language === lang.code
                      ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20'
                      : 'bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white'
                  }`}
                >
                  {lang.label}
                </button>
              ))}
            </div>
          </div>

          {/* Tone */}
          <div className="space-y-3">
            <label className="text-xs font-bold text-gray-500 uppercase tracking-widest">{t.tone}</label>
            <div className="flex gap-2 bg-white/5 p-1 rounded-xl">
              {tones.map((tone) => (
                <button
                  key={tone.code}
                  onClick={() => handleToneChange(tone.code)}
                  className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${
                    profile.tone === tone.code
                      ? 'bg-gray-700 text-white shadow-md'
                      : 'text-gray-400 hover:text-white'
                  }`}
                >
                  {tone.label}
                </button>
              ))}
            </div>
          </div>

        </div>

        <div className="p-6 border-t border-white/10 bg-white/5 flex justify-end">
          <button
            onClick={onClose}
