export const routeVoiceIntent = async (
  text: string,
  userProfile: UserProfile
): Promise<IntentResult> => {
  try {
    const prompt = `
    You are the Voice Router for Aether Health.
    Analyze the user's spoken input and route it to the correct Element.

    ELEMENT DEFINITIONS:
    - FIRE: Symptoms, pain, anxiety, feeling sick, "I don't feel well".
    - EARTH: Medicine authenticity, checking pills, packaging issues.
    - WATER: Water quality, environmental safety, "is this water safe".
    - AIR: Prescriptions, reading doctor's notes, dosage confusion.
    - SPACE: General wellness, translation, cultural advice, holistic health, or if the input is unclear/generic.

    USER INPUT: "${text}"
    USER LANGUAGE: ${userProfile.language}

    Return JSON with 'targetElement' and 'reasoning'.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: intentSchema
      }
    });

    const result = JSON.parse(response.text || '{}');
    return result as IntentResult;
  } catch (error) {
    console.error("Intent Routing Error:", error);
    // Fallback to SPACE
    return { targetElement: ElementType.SPACE, reasoning: "Fallback to universal handler." };
  }
};

export const generateVoiceAudio = async (
  text: string,
  element: ElementType
): Promise<string | undefined> => {
  try {
    // Map Element to Voice
    let voiceName = 'Kore'; // Default (Fire)
    switch (element) {
      case ElementType.FIRE: voiceName = 'Kore'; break;
      case ElementType.EARTH: voiceName = 'Fenrir'; break;
      case ElementType.WATER: voiceName = 'Puck'; break;
      case ElementType.AIR: voiceName = 'Charon'; break;
      case ElementType.SPACE: voiceName = 'Zephyr'; break;
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voiceName },
            },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio;
  } catch (error) {
    console.error("Voice Generation Error:", error);
    return undefined;
  }
}

export const generateAetherResponse = async (
  element: ElementType,
  input: string,
  userProfile: UserProfile,
  imagePart?: string,
  contextData?: Record<string, any> // New parameter for passing data from other elements
): Promise<AnalysisResult> => {

  // MOCK RESPONSE FOR WATER (HydroGuard)
  // Simulating environmental sensor analysis for the demo
  if (element === ElementType.WATER) {
    await new Promise(resolve => setTimeout(resolve, 1500)); // Simulate processing delay

    // Basic mock localization logic for demo purposes
    const isEn = userProfile.language === 'en';
    const isEs = userProfile.language === 'es';

    let summary = 'Simulated analysis of local reservoir inputs indicates slightly elevated turbidity levels due to recent seasonal rainfall.';
    let advice = 'Tap water remains safe for consumption.';
    let reassurance = 'City filtration systems are effectively managing the increased sediment load.';

    if (isEs) {
      summary = 'El análisis simulado indica niveles de turbidez ligeramente elevados debido a las lluvias recientes.';
      advice = 'El agua del grifo sigue siendo segura para el consumo.';
      reassurance = 'Los sistemas de filtración de la ciudad están gestionando eficazmente la carga de sedimentos.';
    }

    return {
      waterQualityRisk: 'Moderate',
      reportSummary: summary,
      reasoningSummary: 'Cross-referenced municipal sensor data with meteorological patterns.',
      safetyAdvice: advice,
      reassuranceLine: reassurance,
      whatThisMeans: isEn ? 'The water might look a bit cloudy, but it is safe.' : 'El agua puede parecer turbia, pero es segura.',
      emotionalState: 'Calm'
    };
  }

  let modelName = 'gemini-3-flash-preview';
  let systemPrompt = SYSTEM_INSTRUCTION;

  // INJECT USER PROFILE
  systemPrompt += `\n
  CRITICAL PROFILE CONTEXT:
  - User Language: ${userProfile.language}
  - Preferred Tone: ${userProfile.tone}
  - Accessibility: ${userProfile.accessibility.largeText ? 'Use simple, clear structure.' : 'Standard.'}

  Generate ALL output in the specified language: ${userProfile.language}.
  Adopt the requested tone: ${userProfile.tone}.
  `;

  let userPrompt = input;
  let responseSchema: any = {};

  switch (element) {
    case ElementType.FIRE:
      systemPrompt += `
      MODE: FIRE (VitalScan).
      Task: Analyze symptoms to reduce anxiety.
      1. Detect emotional tone (fear, panic, neutral).
      2. Identify likely causes using standard medical reasoning.
      3. Assign probabilities.
      4. Reassure the user.
      5. State clearly when to seek help.
      `;
      responseSchema = fireSchema;
      break;

    case ElementType.EARTH:
      modelName = 'gemini-2.5-flash-image';
      systemPrompt += `
      MODE: EARTH (TrueMeds).
      Task: Detect potential counterfeit medicine issues from packaging.
      1. Identify drug name if visible.
      2. Check for visual anomalies.
      3. Provide confidence score (High/Med/Low).
      4. Suggest verification steps.
      `;
      userPrompt = "Analyze this image of medicine packaging for authenticity cues.";
      break;

    case ElementType.SPACE:
      systemPrompt += `
      YOU ARE LIFELOOP (SPACE ELEMENT).
      Your role is to act as the unifying intelligence and central health dashboard.

      CONTEXT FROM OTHER ELEMENTS:
      ${contextData ? JSON.stringify(contextData) : "No specific user data available."}

      USER INPUT (Optional): "${input}"

      TASK:
      1. Synthesize a "Personal Health Snapshot" based on provided context.
      2. If NO context exists:
         - Provide a gentle "Welcome" context encouraging the user to use other elements.
         - Generate generic, safe wellness tips (e.g., hydration, sleep).
         - Generate "General Health Updates" for the News Feed.
      3. If context EXISTS:
         - Synthesize findings into a coherent status.
         - Generate specific "Actionable Tips".
         - Generate News Feed items relevant to the findings (or general if findings are obscure).
      4. Always provide 3-4 items for "News Feed" (Global health updates, verified sources like WHO/CDC).
      5. Create a "Holistic Wellness Strip" with 3-4 exercises.

      OUTPUT MAPPING (JSON):
      - dashboardContext: The synthesis summary or welcome message.
      - actionableTips: List of simple steps.
      - wellnessStrip: Array of exercises with title, type, instruction.
      - newsFeed: Array of news items (headline, summary, source, relevance).
      - safetyAdvice: Guidance on next steps.
      - reassuranceLine: Closing supportive sentence.
      - reasoningSummary: Brief explanation of how you connected the dots.
      `;
      responseSchema = spaceSchema;
      break;

    case ElementType.AIR:
      modelName = 'gemini-2.5-flash-image';
      systemPrompt += `
      MODE: AIR (ClearScript).
      Task: Prevent prescription errors by clarifying instructions.

      INPUT: Prescription Image or Text.
      ACTIONS:
      1. Perform OCR to read text.
      2. Normalize handwriting and correct spellings against known medical drugs.
      3. Extract specific medications, dosages, frequencies, and instructions.
      4. Flag any ambiguities or low confidence reads.
      5. Provide simple patient-safe instructions.

      SAFETY RULES:
      - Never guess. If a word is illegible, flag it.
      - Do not provide diagnosis.

      OUTPUT FIELDS:
      - ocrInterpretation: A summary of what was read.
      - medications: List of identified meds with details.
      - ambiguityFlags: List of unclear items.
      - verificationRequired: Boolean, true if low confidence.
      - safetyAdvice: Warnings or "Ask your pharmacist".
      - reassuranceLine: Calming closing.
      `;
      if (!userPrompt) userPrompt = "Analyze this prescription for clarity and safety.";
      // We do not set responseSchema variable here for config usage because Air uses gemini-2.5-flash-image
      break;
  }

  try {
    const config: any = {
      systemInstruction: systemPrompt,
    };

    // EARTH and AIR use gemini-2.5-flash-image which does NOT support responseMimeType: "application/json"
    if (element !== ElementType.EARTH && element !== ElementType.AIR) {
      config.responseMimeType = "application/json";
      config.responseSchema = responseSchema;
    }

    let contents: any = userPrompt;

    if (imagePart && (element === ElementType.EARTH || element === ElementType.AIR)) {
      contents = {
        parts: [
          { inlineData: { mimeType: 'image/png', data: imagePart } },
          { text: userPrompt }
        ]
      };
    } else if (element === ElementType.SPACE && !userPrompt) {
        // Space might run without direct user text input if just aggregating
        contents = "Generate dashboard.";
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: contents,
      config: config
    });

    const text = response.text;
    if (!text) throw new Error("No response generated");

    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanedText) as AnalysisResult;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { AnalysisResult, ElementType } from '../types';
import { ELEMENTS, SpaceIcon } from '../constants';

interface SpaceDashboardProps {
  results: Record<ElementType, { data: AnalysisResult, timestamp: number } | null>;
  onAskLifeLoop: (input: string) => void;
  loading: boolean;
  t: any;
}

const SpaceDashboard: React.FC<SpaceDashboardProps> = ({ results, onAskLifeLoop, loading, t }) => {
  const [isInputOpen, setIsInputOpen] = useState(false);
  const [localInput, setLocalInput] = useState('');

  // Track if we are in a regeneration state (loading + existing data)
  const spaceData = results[ElementType.SPACE]?.data;
  const isRegenerating = loading && !!spaceData;
  const isInitialLoading = loading && !spaceData;

  // Determine if there is context from other elements
  const hasContext = Object.keys(results).some(
    (key) => key !== ElementType.SPACE && results[key as ElementType] !== null
  );

  // Auto-generate on first load if no data exists
  useEffect(() => {
    if (!spaceData && !loading) {
      onAskLifeLoop("Initial Dashboard Generation");
    }
  }, []); // Run once on mount

  const getTimeAgo = (timestamp: number) => {
    const diff = Date.now() - timestamp;
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return 'Just now';
    if (mins < 60) return `${mins}m ago`;
    return `${Math.floor(mins / 60)}h ago`;
  };

  const handleSubmit = () => {
    if (localInput.trim()) {
      onAskLifeLoop(localInput);
      setLocalInput('');
      setIsInputOpen(false);
    }
  };

  const handleRegenerate = () => {
    onAskLifeLoop("Regenerate insights based on latest context");
  };

  return (
    <div className="h-full flex flex-col gap-6 animate-fade-in text-white">

      {/* 1. HEADER SECTION */}
      <header className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-display font-bold bg-clip-text text-transparent bg-gradient-to-r from-violet-400 to-fuchsia-400">
            Your Health in Context
          </h2>
          <div className="flex items-center gap-2 mt-2">
             <div className="flex -space-x-2">
               {[ElementType.FIRE, ElementType.WATER, ElementType.AIR, ElementType.EARTH].map(el => (
                 <div key={el} className={`w-6 h-6 rounded-full border-2 border-[#0B0F17] flex items-center justify-center ${results[el] ? ELEMENTS[el].bg : 'bg-gray-800'}`}>
                    <div className={`w-2 h-2 rounded-full ${results[el] ? 'bg-white' : 'bg-gray-600'}`} />
                 </div>
               ))}
             </div>
             <span className="text-xs text-gray-500 ml-2">
               {hasContext ? "Data synced from modules" : "Waiting for module data..."}
             </span>
             {isRegenerating && (
                <span className="ml-4 text-xs font-bold text-violet-400 animate-pulse flex items-center gap-1">
                  <span className="w-1.5 h-1.5 bg-violet-400 rounded-full"/> Updating...
                </span>
             )}
          </div>
        </div>

        {/* Ask / Regenerate Actions */}
        <div className="flex gap-2">
          {spaceData && (
             <button
               onClick={handleRegenerate}
               disabled={loading}
               className={`flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-full border border-white/10 transition-all text-xs font-bold text-violet-300 uppercase tracking-wide ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
             >
                <svg className={`w-3 h-3 ${loading ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                </svg>
                {loading ? 'Refreshing' : 'Regenerate'}
             </button>
          )}

          <button 
            onClick={() => setIsInputOpen(true)}
            className="flex items-center gap-2 px-5 py-2.5 bg-violet-600/20 hover:bg-violet-600/30 rounded-full border border-violet-500/30 transition-all text-sm font-medium text-violet-200"
          >
            <SpaceIcon className="w-4 h-4" />
            <span>Ask LifeLoop</span>
          </button>
        </div>
      </header>

      {/* 2. HEALTH SNAPSHOT CARDS */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[ElementType.FIRE, ElementType.WATER, ElementType.AIR, ElementType.EARTH].map(el => {
           const config = ELEMENTS[el];
           const res = results[el];
           const Icon = config.icon;

           let summary = "No data yet.";
           if (res) {
             if (el === ElementType.FIRE) summary = res.data.whatThisMeans || res.data.reassuranceLine;
             if (el === ElementType.WATER) summary = res.data.reportSummary || "Water analysis complete.";
             if (el === ElementType.AIR) summary = res.data.reassuranceLine || "Prescription processed.";
             if (el === ElementType.EARTH) summary = res.data.medicineIdentified ? `Identified: ${res.data.medicineIdentified}` : "Packaging verified.";
           }

