export const routeVoiceIntent = async (
  text: string,
  userProfile: UserProfile
): Promise<IntentResult> => {
  try {
    const prompt = `
    You are the Voice Router for Aether Health.
    Analyze the user's spoken input and determine the correct Action and Target.

    ACTIONS:
    - NAVIGATE_DASHBOARD: User wants to go back, go home, go to main menu, or exit the current screen.
    - NAVIGATE_ELEMENT: User wants to open a specific tool, module, or has a query suited for a specific element.
    - EXPLAIN: User is asking for help about the app, asking what an element does, or needs guidance.

    ELEMENT DEFINITIONS (for NAVIGATE_ELEMENT):
    - FIRE: Symptoms, pain, anxiety, feeling sick, "I don't feel well", VitalScan.
    - EARTH: Medicine authenticity, checking pills, packaging issues, TrueMeds.
    - WATER: Water quality, environmental safety, "is this water safe", HydroGuard.
    - AIR: Prescriptions, reading doctor's notes, dosage confusion, ClearScript.
    - SPACE: General wellness, translation, cultural advice, holistic health, LifeLoop.

    USER INPUT: "${text}"
    USER LANGUAGE: ${userProfile.language}

    Return JSON with 'action', 'targetElement' (if applicable), and 'reasoning'.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: intentSchema
      }
    });

    const result = JSON.parse(response.text || '{}');
    return result as IntentResult;
  } catch (error) {
    console.error("Intent Routing Error:", error);
    // Fallback to SPACE
    return { action: 'NAVIGATE_ELEMENT', targetElement: ElementType.SPACE, reasoning: "Fallback to universal handler." };
  }
};

export const generateVoiceAudio = async (
  text: string,
  element: ElementType
): Promise<string | undefined> => {
  try {
    // Map Element to Voice
    let voiceName = 'Kore'; // Default (Fire)
    switch (element) {
      case ElementType.FIRE: voiceName = 'Kore'; break;
      case ElementType.EARTH: voiceName = 'Fenrir'; break;
      case ElementType.WATER: voiceName = 'Puck'; break;
      case ElementType.AIR: voiceName = 'Charon'; break;
      case ElementType.SPACE: voiceName = 'Zephyr'; break;
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: voiceName },
            },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio;
  } catch (error) {
    console.error("Voice Generation Error:", error);
    return undefined;
  }
}

export const generateAetherResponse = async (
  element: ElementType,
  input: string,
  userProfile: UserProfile,
  imagePart?: string,
  contextData?: Record<string, any> // New parameter for passing data from other elements
): Promise<AnalysisResult> => {

  // MOCK RESPONSE FOR WATER (HydroGuard)
  // Simulating environmental sensor analysis for the demo
  if (element === ElementType.WATER) {
    await new Promise(resolve => setTimeout(resolve, 1500)); // Simulate processing delay

    // Basic mock localization logic for demo purposes
    const isEn = userProfile.language === 'en';
    const isEs = userProfile.language === 'es';

    let summary = 'Simulated analysis of local reservoir inputs indicates slightly elevated turbidity levels due to recent seasonal rainfall.';
    let advice = 'Tap water remains safe for consumption.';
    let reassurance = 'City filtration systems are effectively managing the increased sediment load.';

    if (isEs) {
      summary = 'El análisis simulado indica niveles de turbidez ligeramente elevados debido a las lluvias recientes.';
      advice = 'El agua del grifo sigue siendo segura para el consumo.';
      reassurance = 'Los sistemas de filtración de la ciudad están gestionando eficazmente la carga de sedimentos.';
    }

    return {
      waterQualityRisk: 'Moderate',
      reportSummary: summary,
      reasoningSummary: 'Cross-referenced municipal sensor data with meteorological patterns.',
      safetyAdvice: advice,
      reassuranceLine: reassurance,
      whatThisMeans: isEn ? 'The water might look a bit cloudy, but it is safe.' : 'El agua puede parecer turbia, pero es segura.',
      emotionalState: 'Calm'
    };
  }

  let modelName = 'gemini-3-flash-preview';
  let systemPrompt = SYSTEM_INSTRUCTION;

  // INJECT USER PROFILE
  systemPrompt += `\n
  CRITICAL PROFILE CONTEXT:
  - User Language: ${userProfile.language}
  - Preferred Tone: ${userProfile.tone}
  - Accessibility: ${userProfile.accessibility.largeText ? 'Use simple, clear structure.' : 'Standard.'}

  Generate ALL output in the specified language: ${userProfile.language}.
  Adopt the requested tone: ${userProfile.tone}.
  `;

  let userPrompt = input;
  let responseSchema: any = {};

  switch (element) {
    case ElementType.FIRE:
      systemPrompt += `
      MODE: FIRE (VitalScan).
      Task: Analyze symptoms to reduce anxiety.
      1. Detect emotional tone (fear, panic, neutral).
      2. Identify likely causes using standard medical reasoning.
      3. Assign probabilities.
      4. Reassure the user.
      5. State clearly when to seek help.
      `;
      responseSchema = fireSchema;
      break;

    case ElementType.EARTH:
      modelName = 'gemini-2.5-flash-image';
      systemPrompt += `
      MODE: EARTH (TrueMeds).
      Task: Detect potential counterfeit medicine issues from packaging.
      1. Identify drug name if visible.
      2. Check for visual anomalies.
      3. Provide confidence score (High/Med/Low).
      4. Suggest verification steps.
      `;
      userPrompt = "Analyze this image of medicine packaging for authenticity cues.";
      break;

    case ElementType.SPACE:
      systemPrompt += `
      YOU ARE LIFELOOP (SPACE ELEMENT).
      Your role is to act as the unifying intelligence and central health dashboard.

      CONTEXT FROM OTHER ELEMENTS:
      ${contextData ? JSON.stringify(contextData) : "No specific user data available."}

      USER INPUT (Optional): "${input}"

      TASK:
      1. Synthesize a "Personal Health Snapshot" based on provided context.
      2. If NO context exists:
         - Provide a gentle "Welcome" context encouraging the user to use other elements.
         - Generate generic, safe wellness tips (e.g., hydration, sleep).
         - Generate "General Health Updates" for the News Feed.
      3. If context EXISTS:
         - Synthesize findings into a coherent status.
         - Generate specific "Actionable Tips".
         - Generate News Feed items relevant to the findings (or general if findings are obscure).
      4. Always provide 3-4 items for "News Feed" (Global health updates, verified sources like WHO/CDC).
      5. Create a "Holistic Wellness Strip" with 3-4 exercises.
         IMPORTANT MANDATE: You MUST ALWAYS include "Box Breathing" as one of the exercises in the wellnessStrip.
         - Title: Box Breathing
         - Type: Breathing
         - Instruction: "Inhale for 4 seconds, Hold for 4 seconds, Exhale for 4 seconds, Hold for 4 seconds."

      OUTPUT MAPPING (JSON):
      - dashboardContext: The synthesis summary or welcome message.
      - actionableTips: List of simple steps.
      - wellnessStrip: Array of exercises with title, type, instruction (Must include Box Breathing).
      - newsFeed: Array of news items (headline, summary, source, relevance).
      - safetyAdvice: Guidance on next steps.
      - reassuranceLine: Closing supportive sentence.
      - reasoningSummary: Brief explanation of how you connected the dots.
      `;
      responseSchema = spaceSchema;
      break;

    case ElementType.AIR:
      modelName = 'gemini-2.5-flash-image';
      systemPrompt += `
      MODE: AIR (ClearScript).
      Task: Prevent prescription errors by clarifying instructions.

      INPUT: Prescription Image or Text.
      ACTIONS:
      1. Perform OCR to read text.
      2. Normalize handwriting and correct spellings against known medical drugs.
      3. Extract specific medications, dosages, frequencies, and instructions.
      4. Flag any ambiguities or low confidence reads.
      5. Provide simple patient-safe instructions.

      SAFETY RULES:
      - Never guess. If a word is illegible, flag it.
      - Do not provide diagnosis.

      OUTPUT FIELDS:
      - ocrInterpretation: A summary of what was read.
      - medications: List of identified meds with details.
      - ambiguityFlags: List of unclear items.
      - verificationRequired: Boolean, true if low confidence.
      - safetyAdvice: Warnings or "Ask your pharmacist".
      - reassuranceLine: Calming closing.
      `;
      if (!userPrompt) userPrompt = "Analyze this prescription for clarity and safety.";
      // We do not set responseSchema variable here for config usage because Air uses gemini-2.5-flash-image
      break;
  }

  try {
    const config: any = {
      systemInstruction: systemPrompt,
    };

    // EARTH and AIR use gemini-2.5-flash-image which does NOT support responseMimeType: "application/json"
    if (element !== ElementType.EARTH && element !== ElementType.AIR) {
      config.responseMimeType = "application/json";
      config.responseSchema = responseSchema;
    }

    let contents: any = userPrompt;

    if (imagePart && (element === ElementType.EARTH || element === ElementType.AIR)) {
      contents = {
        parts: [
          { inlineData: { mimeType: 'image/png', data: imagePart } },
          { text: userPrompt }
        ]
      };
    } else if (element === ElementType.SPACE && !userPrompt) {
        // Space might run without direct user text input if just aggregating
        contents = "Generate dashboard.";
    }

    const response = await ai.models.generateContent({
      model: modelName,
      contents: contents,
      config: config
    });

    const text = response.text;
    if (!text) throw new Error("No response generated");

    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(cleanedText) as AnalysisResult;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { UserProfile } from '../types';

interface AIBuddyProps {
  onTranscript: (text: string) => void;
  userProfile: UserProfile;
  t: any;
  feedbackMsg: string | null;
  loading: boolean;
  isPlayingAudio: boolean;
}

const AIBuddy: React.FC<AIBuddyProps> = ({ 
  onTranscript, 
  userProfile, 
  t, 
  feedbackMsg, 
  loading,
  isPlayingAudio 
}) => {
  const [isListening, setIsListening] = useState(false);
  const [localMessage, setLocalMessage] = useState<string | null>(null);
  const [buddyState, setBuddyState] = useState<'idle' | 'listening' | 'thinking' | 'speaking'>('idle');

  const recognitionRef = useRef<any>(null);

  // Sync state with props
  useEffect(() => {
    if (loading) {
      setBuddyState('thinking');
    } else if (isPlayingAudio) {
      setBuddyState('speaking');
    } else if (isListening) {
      setBuddyState('listening');
    } else {
      setBuddyState('idle');
    }
  }, [loading, isPlayingAudio, isListening]);

  // Sync feedback message
  useEffect(() => {
    if (feedbackMsg) {
      setLocalMessage(feedbackMsg);
      const timer = setTimeout(() => setLocalMessage(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [feedbackMsg]);

  // Setup Speech Recognition
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = userProfile.language;

      recognition.onstart = () => {
        setIsListening(true);
        setLocalMessage(t.voice.listening);
      };

      recognition.onend = () => {
        setIsListening(false);
        // Don't clear message immediately if processing
      };

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        onTranscript(transcript);
      };

      recognition.onerror = (event: any) => {
        console.error("Speech error", event.error);
        setIsListening(false);
        setLocalMessage(t.voice.error);
        setTimeout(() => setLocalMessage(null), 3000);
      };

      recognitionRef.current = recognition;
    }
  }, [userProfile.language, onTranscript, t]);

  const toggleListening = () => {
    if (!recognitionRef.current) {
      setLocalMessage("Voice not supported");
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      recognitionRef.current.start();
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end pointer-events-none">

      {/* Chat Bubble */}
      {localMessage && (
        <div className="mb-4 mr-2 bg-white/10 backdrop-blur-md border border-white/20 p-4 rounded-2xl rounded-tr-sm shadow-xl max-w-xs animate-slide-up pointer-events-auto">
          <p className="text-sm font-medium text-white">{localMessage}</p>
        </div>
      )}

      {/* Buddy Orb */}
      <button 
        onClick={toggleListening}
        className={`pointer-events-auto relative w-16 h-16 rounded-full flex items-center justify-center transition-all duration-500 hover:scale-110 focus:outline-none ${
          buddyState === 'thinking' ? 'animate-bounce' : ''
        }`}
      >
        {/* Core Glow */}
        <div className={`absolute inset-0 rounded-full blur-md transition-all duration-500 ${
          buddyState === 'listening' ? 'bg-red-500/50 scale-125' : 
          buddyState === 'thinking' ? 'bg-violet-500/50 scale-110' :
          buddyState === 'speaking' ? 'bg-emerald-500/50 scale-125' :
          'bg-blue-500/30'
        }`}></div>

        {/* Outer Ring */}
        <div className={`absolute inset-0 border-2 rounded-full transition-all duration-500 ${
          buddyState === 'listening' ? 'border-red-400 border-dashed animate-spin-slow' :
          buddyState === 'thinking' ? 'border-violet-400 border-double animate-ping' :
          buddyState === 'speaking' ? 'border-emerald-400 animate-pulse' :
          'border-white/20'
        }`}></div>

        {/* Inner Orb */}
        <div className={`relative w-12 h-12 rounded-full shadow-inner flex items-center justify-center overflow-hidden backdrop-blur-sm border transition-colors duration-500 ${
           buddyState === 'listening' ? 'bg-gradient-to-br from-red-500 to-rose-700 border-red-300' :
           buddyState === 'thinking' ? 'bg-gradient-to-br from-violet-500 to-fuchsia-700 border-violet-300' :
           buddyState === 'speaking' ? 'bg-gradient-to-br from-emerald-500 to-teal-700 border-emerald-300' :
           'bg-gradient-to-br from-blue-600 to-indigo-800 border-white/30'
        }`}>
           {/* Face / Icon */}
           {buddyState === 'listening' ? (
             <svg className="w-6 h-6 text-white animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
             </svg>
           ) : buddyState === 'thinking' ? (
             <svg className="w-6 h-6 text-white animate-spin" fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
             </svg>
           ) : buddyState === 'speaking' ? (
             <div className="flex gap-0.5 items-center justify-center h-4">
               <div className="w-1 bg-white animate-wave rounded-full h-full"></div>
               <div className="w-1 bg-white animate-wave rounded-full h-3 animation-delay-100"></div>
               <div className="w-1 bg-white animate-wave rounded-full h-4 animation-delay-200"></div>
             </div>
           ) : (
             <svg className="w-6 h-6 text-white/90" fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
             </svg>
           )}
        </div>
      </button>

      {/* Help Label (Only shows when idle and no message) */}
      {!localMessage && buddyState === 'idle' && (
        <span className="mt-2 text-[10px] font-bold text-white/50 uppercase tracking-widest bg-black/40 px-2 py-1 rounded backdrop-blur-sm pointer-events-auto">
          Tap for Help
        </span>
      )}
    </div>
  );
};

export default AIBuddy;

import React, { useState, useRef } from 'react';
import { ElementType, AnalysisResult, UserProfile } from './types';
import { ELEMENTS } from './constants';
import { TRANSLATIONS } from './translations';
import { generateAetherResponse, routeVoiceIntent, generateVoiceAudio } from './services/geminiService';
import DashboardGrid from './components/DashboardGrid';
import OutputDisplay from './components/OutputDisplay';
import TrustPanel from './components/TrustPanel';
import SettingsPanel from './components/SettingsPanel';
import LandingPage from './components/LandingPage';
import VoiceInput from './components/VoiceInput';
import SpaceDashboard from './components/SpaceDashboard';
import AIBuddy from './components/AIBuddy';

type ViewState = 'LANDING' | 'DASHBOARD' | 'MODULE';

// Audio Decode Helper
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('LANDING');
  const [currentElement, setCurrentElement] = useState<ElementType | null>(null);

  // User Profile State
  const [userProfile, setUserProfile] = useState<UserProfile>({
    language: 'en',
    tone: 'calm',
    voiceResponse: true,
    accessibility: { largeText: false }
  });
  const [showSettings, setShowSettings] = useState(false);
  const [feedbackMsg, setFeedbackMsg] = useState<string | null>(null);

  // Input & Results State
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Global Result Map for Context
  const [results, setResults] = useState<Record<ElementType, { data: AnalysisResult, timestamp: number } | null>>({
    [ElementType.FIRE]: null,
    [ElementType.WATER]: null,
    [ElementType.AIR]: null,
    [ElementType.EARTH]: null,
    [ElementType.SPACE]: null,
  });

  // Global Voice State
  const [isRoutingVoice, setIsRoutingVoice] = useState(false);

  // TTS State
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  // Translation Helper
  const t = TRANSLATIONS[userProfile.language];

  // Helper to get current result
  const currentResult = currentElement ? results[currentElement]?.data || null : null;

  const handleElementSelect = (el: ElementType) => {
    setCurrentElement(el);
    setView('MODULE');

    // Clear transient inputs
    setInputText('');
    setSelectedImage(null);
    setError(null);
    stopAudio();
    setAudioBase64(null);

    // If Space is selected and has no data, maybe auto-trigger? 
    // For now we wait for user interaction or they see the empty state.
  };

  const handleBack = () => {
    setView('DASHBOARD');
    setCurrentElement(null);
    stopAudio();
    setAudioBase64(null);
  };

  const handleUpdateProfile = (newProfile: UserProfile) => {
    setUserProfile(newProfile);
    setFeedbackMsg(TRANSLATIONS[newProfile.language].updated);
    setTimeout(() => setFeedbackMsg(null), 3000);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Content = base64String.split(',')[1];
        setSelectedImage(base64Content);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleLocalVoiceInput = (transcript: string) => {
    setInputText(transcript);
  };

  const handleGlobalVoiceInput = async (transcript: string) => {
    if (!transcript) return;
    setIsRoutingVoice(true);
    setFeedbackMsg(t.voice.processing);

    try {
      const routingResult = await routeVoiceIntent(transcript, userProfile);

      if (routingResult.action === 'NAVIGATE_DASHBOARD') {
        setFeedbackMsg("Navigating to Dashboard...");
        setTimeout(() => setFeedbackMsg(null), 3000);
        handleBack();
      } else if (routingResult.action === 'NAVIGATE_ELEMENT' && routingResult.targetElement) {
        setFeedbackMsg(`${t.voice.routed} ${t.elements[routingResult.targetElement].name}`);
        setTimeout(() => setFeedbackMsg(null), 3000);
        handleElementSelect(routingResult.targetElement);
        // Pre-fill text if it was a query
        setInputText(transcript);
      } else if (routingResult.action === 'EXPLAIN') {
         // Handle explanation by sending to Space logic temporarily or just speaking
         setFeedbackMsg(routingResult.reasoning || "I can help with that.");

         // If we are in Space, ask LifeLoop
         if (currentElement === ElementType.SPACE) {
            handleAction(transcript);
         } else {
            // If we are elsewhere, maybe just read the reasoning out loud if voice is on?
            // For now, let's just show the feedback msg.
         }
      } else {
         // Fallback default behavior
         setFeedbackMsg("I didn't quite get that command.");
         setTimeout(() => setFeedbackMsg(null), 2000);
      }

    } catch (err) {
      console.error(err);
      setFeedbackMsg(t.voice.error);
    } finally {
      setIsRoutingVoice(false);
    }
  };

  const playAudio = async (base64: string) => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      }

      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      const bytes = decode(base64);
      const buffer = audioContextRef.current.createBuffer(1, bytes.length / 2, 24000);
      const channelData = buffer.getChannelData(0);
      const dataInt16 = new Int16Array(bytes.buffer);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsPlaying(false);

      sourceRef.current = source;
      source.start();
      setIsPlaying(true);
    } catch (e) {
      console.error("Audio playback error", e);
      setIsPlaying(false);
    }
  };

  const stopAudio = () => {
    if (sourceRef.current) {
      sourceRef.current.stop();
      sourceRef.current = null;
    }
    setIsPlaying(false);
  };

  const handleClear = () => {
    setInputText('');
    setSelectedImage(null);
    setError(null);
    stopAudio();
    setAudioBase64(null);

    // Also clear the result for the current element in the map
    if (currentElement) {
       setResults(prev => ({
         ...prev,
         [currentElement]: null
       }));
    }
  };

  const handleAction = async (overrideInput?: string) => {
    if (!currentElement) return;

    setLoading(true);
    setError(null);
    stopAudio();
    setAudioBase64(null);

    const inputToUse = overrideInput || inputText;

    try {
      // Prepare context for Space
      let contextData = {};
      if (currentElement === ElementType.SPACE) {
         contextData = (Object.keys(results) as ElementType[]).reduce((acc, key) => {
            const val = results[key];
            if (key !== ElementType.SPACE && val) {
              acc[key] = val.data;
            }
            return acc;
         }, {} as any);
      }

      const response = await generateAetherResponse(
        currentElement, 
        inputToUse, 
        userProfile,
        selectedImage || undefined,
        contextData
      );

      // Update Results Map
      setResults(prev => ({
        ...prev,
        [currentElement]: { data: response, timestamp: Date.now() }
      }));

      // Trigger Voice Response if enabled
      if (userProfile.voiceResponse) {
        let textToSpeak = response.reassuranceLine;
        if (response.safetyAdvice) textToSpeak += ". " + response.safetyAdvice;
        if (response.whatThisMeans) textToSpeak = response.whatThisMeans + ". " + textToSpeak;

        if (textToSpeak.length > 300) textToSpeak = textToSpeak.substring(0, 300) + "...";

        const audio = await generateVoiceAudio(textToSpeak, currentElement);
        if (audio) {
          setAudioBase64(audio);
          playAudio(audio);
        }
      }

    } catch (err) {
      setError("Aether could not complete the analysis. Please try again.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const currentConfig = currentElement ? ELEMENTS[currentElement] : null;
  const currentLoc = currentConfig ? t.elements[currentConfig.id] : null;

  if (view === 'LANDING') {
    return (
      <LandingPage 
        onEnter={() => setView('DASHBOARD')} 
        onLaunchElement={handleElementSelect}
        t={t} 
      />
    );
  }

  return (
    <div className={`min-h-screen font-sans selection:bg-white/20 ${userProfile.accessibility.largeText ? 'text-lg' : ''} animate-fade-in`}>

      {/* Navigation */}
      <nav className="border-b border-white/5 bg-obsidian/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={handleBack}>
             <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 flex items-center justify-center shadow-lg shadow-blue-900/20">
               <span className="text-white font-bold text-lg">Ah</span>
             </div>
             <span className="text-xl font-display font-semibold text-white tracking-tight">{t.appTitle}</span>
          </div>
          <div className="flex items-center gap-4">
             {/* Note: Feedback message moved to AIBuddy */}

             {/* Removing the old VoiceInput from header as AIBuddy replaces it globally */}

             <button 
               onClick={() => setShowSettings(true)}
               className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-gray-400 hover:text-white hover:bg-white/10 transition-all border border-transparent hover:border-white/20"
             >
               <span className="sr-only">Settings</span>
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
               </svg>
             </button>
             <div className="w-10 h-10 rounded-full bg-gradient-to-br from-gray-700 to-gray-900 border border-white/10 flex items-center justify-center text-xs font-bold text-gray-400">
               {userProfile.language.toUpperCase()}
             </div>
          </div>
        </div>
      </nav>

      {showSettings && (
        <SettingsPanel 
          profile={userProfile} 
          onUpdate={handleUpdateProfile} 
          onClose={() => setShowSettings(false)} 
          t={t}
        />
      )}

      {/* GLOBAL AI BUDDY */}
      <AIBuddy 
        onTranscript={handleGlobalVoiceInput}
        userProfile={userProfile}
        t={t}
        feedbackMsg={feedbackMsg}
        loading={loading || isRoutingVoice}
        isPlayingAudio={isPlaying}
      />

      <main className="max-w-7xl mx-auto px-6 py-12 relative flex-1 flex flex-col">

        {/* VIEW: DASHBOARD */}
        {view === 'DASHBOARD' && (
          <div className="animate-fade-in">
            <header className="text-center mb-16 relative">
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[300px] bg-indigo-500/10 rounded-full blur-[100px] -z-10"></div>
              <h1 className="text-5xl md:text-6xl font-display font-medium text-white mb-4 tracking-tight text-glow">
                {t.dashboardTitle}
              </h1>
              <p className="text-xl text-gray-400 font-light">
                {t.dashboardSubtitle}
              </p>
            </header>

            <div className="flex justify-center mb-12">
               {/* Visual voice cue handled by Buddy now */}
            </div>

            <DashboardGrid onSelect={handleElementSelect} t={t} />

            <footer className="mt-24 text-center">
              <div className="w-24 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent mx-auto mb-6"></div>
              <p className="text-sm text-gray-500 font-display tracking-widest uppercase opacity-70">
                "{t.footer}"
              </p>
            </footer>
          </div>
        )}

        {/* VIEW: MODULE */}
        {view === 'MODULE' && currentConfig && currentLoc && (
          <div className="animate-fade-in flex-1 flex flex-col">

            {/* Module Header (Simplified for Space) */}
            {currentElement !== ElementType.SPACE && (
              <div className="flex items-center gap-4 mb-10">
                <button 
                  onClick={handleBack}
                  className="group flex items-center gap-2 text-gray-400 hover:text-white transition-colors"
                >
                  <div className="w-8 h-8 rounded-full border border-white/10 flex items-center justify-center group-hover:border-white/30">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                  </div>
                  <span className="text-sm font-medium">{t.backToDashboard}</span>
                </button>
                <div className="h-6 w-px bg-white/10 mx-2"></div>
                <h2 className={`text-2xl font-display font-semibold text-transparent bg-clip-text bg-gradient-to-r ${currentConfig.gradientFrom.replace('/20','')} ${currentConfig.gradientTo.replace('/20','')}`}>
                  {currentLoc.name}
                </h2>

                {audioBase64 && (
                  <div className="ml-auto flex items-center gap-2">
                     {isPlaying ? (
                       <button onClick={stopAudio} className="flex items-center gap-2 px-4 py-2 bg-red-500/20 text-red-400 rounded-full text-sm font-medium hover:bg-red-500/30 transition-colors">
                         <span className="animate-pulse">●</span> {t.voice.mute}
                       </button>
                     ) : (
                       <button onClick={() => playAudio(audioBase64)} className="flex items-center gap-2 px-4 py-2 bg-emerald-500/20 text-emerald-400 rounded-full text-sm font-medium hover:bg-emerald-500/30 transition-colors">
                         <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                         {t.voice.replay}
                       </button>
                     )}
                  </div>
                )}
              </div>
            )}

            {currentElement === ElementType.SPACE ? (
              <>
               <div className="mb-6 flex justify-start">
                   <button 
                      onClick={handleBack}
                      className="group flex items-center gap-2 text-gray-400 hover:text-white transition-colors"
                    >
                      <div className="w-8 h-8 rounded-full border border-white/10 flex items-center justify-center group-hover:border-white/30">
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                      </div>
                      <span className="text-sm font-medium">{t.backToDashboard}</span>
                    </button>
               </div>
               <SpaceDashboard 
                  results={results}
                  onAskLifeLoop={(input) => handleAction(input)}
                  loading={loading}
                  t={t}
               />
              </>
            ) : (
              /* Standard Layout for Fire, Water, Air, Earth */
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                {/* LEFT: Input Column (3 cols) */}
                <div className="lg:col-span-3 space-y-6">
                  <div className="glass-card p-6 rounded-2xl">
                      <div className="flex items-center gap-3 mb-6">
                        <div className={`p-2 rounded-lg bg-gradient-to-br ${currentConfig.gradientFrom} ${currentConfig.gradientTo} text-white`}>
                          <currentConfig.icon className="w-5 h-5" />
                        </div>
                        <div className="text-sm font-bold text-gray-300 uppercase tracking-wider">{t.inputLabel}</div>
                      </div>

                      <div className="space-y-6">
                        {currentConfig.inputType === 'text' && (
                          <div className="space-y-3">
                            <textarea
                              className="w-full bg-black/20 border border-white/10 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-white/10 focus:border-white/20 transition-all resize-none h-48 text-sm leading-relaxed"
                              placeholder={currentLoc.placeholder}
                              value={inputText}
                              onChange={(e) => setInputText(e.target.value)}
                            />
                            {/* Local Voice Input Removed - handled by Buddy */}
                          </div>
                        )}

                        {currentConfig.inputType === 'image' && (
                          <div className="relative group">
                            <input 
                                type="file" 
                                accept="image/*" 
                                onChange={handleImageUpload} 
                                className="hidden" 
                                id="image-upload" 
                              />
                            <label htmlFor="image-upload" className="block cursor-pointer">
                              <div className="border-2 border-dashed border-white/10 rounded-xl p-8 text-center bg-white/5 hover:bg-white/10 hover:border-white/20 transition-all">
                                  {selectedImage ? (
                                    <div className="relative rounded-lg overflow-hidden h-32 w-full">
                                      <img src={`data:image/png;base64,${selectedImage}`} alt="Upload" className="w-full h-full object-cover" />
                                      <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                        <span className="text-xs text-white">{t.changeImage}</span>
                                      </div>
                                    </div>
                                  ) : (
                                    <div className="flex flex-col items-center">
                                      <svg className="w-8 h-8 text-gray-500 mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                                      <span className="text-sm text-gray-400">{t.uploadPhoto}</span>
                                    </div>
                                  )}
                              </div>
                            </label>
                          </div>
                        )}

                        {currentConfig.inputType === 'mock_action' && (
                          <div className="p-4 bg-white/5 rounded-xl border border-white/5 text-center">
                            <p className="text-sm text-gray-400">{t.initSim}</p>
                          </div>
                        )}

                        <div className="flex items-stretch gap-3">
                          {currentConfig.inputType !== 'mock_action' && (
                            <button
                              onClick={handleClear}
                              disabled={loading || (!inputText && !selectedImage)}
                              className="px-4 rounded-xl font-bold text-gray-400 bg-white/5 border border-white/10 hover:bg-white/10 hover:text-white transition-all disabled:opacity-30 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                              title="Clear Input"
                            >
                              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                              </svg>
                              <span className="hidden md:inline text-xs uppercase tracking-wider">Clear</span>
                            </button>
                          )}

                          <button
                            onClick={() => handleAction()}
                            disabled={loading || (currentConfig.inputType === 'text' && !inputText) || (currentConfig.inputType === 'image' && !selectedImage)}
                            className={`
                              flex-1 py-4 rounded-xl font-bold text-white shadow-lg transition-all transform active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed
                              bg-gradient-to-r ${currentConfig.gradientFrom.replace('/20','')} ${currentConfig.gradientTo.replace('/20','')}
                              hover:shadow-xl hover:brightness-110
                            `}
                          >
                            {loading ? (
                              <div className="flex items-center justify-center gap-2">
                                  <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                                  <span>{t.thinking}</span>
                              </div>
                            ) : (
                              <span>{t.analyze}</span>
                            )}
                          </button>
                        </div>

                        {error && <p className="text-red-400 text-xs text-center">{error}</p>}
                      </div>
                  </div>
                </div>

                {/* CENTER: Output Column (6 cols) */}
                <div className="lg:col-span-6">
                  {currentResult ? (
                    <OutputDisplay element={currentElement} result={currentResult} t={t} />
                  ) : (
                    <div className="h-full min-h-[400px] glass-card rounded-3xl flex flex-col items-center justify-center text-center p-8 opacity-50 border-dashed border-2 border-white/5">
                      <div className="w-20 h-20 rounded-full bg-white/5 flex items-center justify-center mb-6 animate-pulse-slow">
                          <currentConfig.icon className="w-8 h-8 text-gray-500" />
                      </div>
                      <h3 className="text-xl text-gray-300 font-display mb-2">{t.readyForAnalysis}</h3>
                      <p className="text-gray-500 max-w-xs mx-auto">
                        {t.readyDesc}
                      </p>
                    </div>
                  )}
                </div>

                {/* RIGHT: Trust Column (3 cols) */}
                <div className="lg:col-span-3">
                  <TrustPanel 
                    emotionalTone={currentResult?.emotionalState} 
                    reasoning={currentResult?.reasoningSummary}
                    t={t}
                  />

                  {/* Decorative */}
                  {!currentResult && (
                    <div className="mt-8 p-6 text-center opacity-30">
                      <div className="w-16 h-1 bg-white/20 mx-auto mb-4"></div>
                      <p className="text-xs font-serif italic text-gray-400">
                        Aether Health operates on a responsible AI framework prioritizing safety and clarity.
                      </p>
                    </div>
                  )}
                </div>

              </div>
            )}
          </div>
        )}

      </main>
    </div>
  );
};

