               onClick={onAnalyze}
               className="w-full mt-6 py-4 bg-white text-black font-bold rounded-2xl hover:bg-cyan-50 transition-all uppercase tracking-[0.2em] text-xs shadow-xl"
             >
               Initiate Decoding
