          {loading && (
             <div className="h-[400px] border border-white/5 bg-[#151A1C] rounded-3xl flex flex-col items-center justify-center p-12">
                <h3 className="text-xs font-bold text-cyan-400 uppercase tracking-widest mb-8 animate-pulse">Processing Sequence</h3>
                <div className="space-y-6 w-full max-w-md">
                   {PROCESSING_STEPS.map((step, idx) => (
                      <div key={idx} className={`flex items-center gap-4 transition-all duration-500 ${idx <= currentStep ? 'opacity-100' : 'opacity-30'}`}>
                         <div className={`w-6 h-6 rounded-full flex items-center justify-center border ${
                           idx < currentStep ? 'bg-cyan-500 border-cyan-500 text-black' : 
                           idx === currentStep ? 'bg-transparent border-cyan-500 text-cyan-500 animate-spin' :
                           'bg-transparent border-gray-600 text-gray-600'
                         }`}>
                            {idx < currentStep ? (
                              <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
                            ) : idx === currentStep ? (
                              <span className="w-1 h-1 rounded-full bg-cyan-400"></span>
                            ) : (
                              <span className="text-[10px]">{idx + 1}</span>
                            )}
                         </div>
                         <span className={`text-sm font-mono ${idx === currentStep ? 'text-white' : 'text-gray-400'}`}>{step}</span>
                      </div>
                   ))}
                </div>
             </div>
          )}

          {!loading && !hasResult && (
             <div className="h-[400px] border border-dashed border-white/5 rounded-3xl flex items-center justify-center text-center p-12">
                <div>
                   <p className="text-cyan-500/40 font-mono text-sm mb-2">Waiting for data input...</p>
                   <p className="text-white/20 text-xs">Aether intelligence will render instructions here.</p>
                </div>
             </div>
          )}

          {!loading && hasResult && result && (
            <div className="space-y-8 animate-slide-up">

               {/* 1. OCR Summary */}
               <section>
                  <h3 className="text-[10px] font-bold text-cyan-500/60 uppercase tracking-[0.3em] mb-4">Transcript Overview</h3>
                  <div className="p-6 rounded-2xl bg-[#1C2325] border border-cyan-500/10 text-cyan-100/80 font-mono text-xs leading-relaxed shadow-inner">
                    {result.data.ocrInterpretation}
                  </div>
               </section>

               {/* 2. Decoded Medications */}
               <section>
                  <h3 className="text-[10px] font-bold text-cyan-500/60 uppercase tracking-[0.3em] mb-4">Medication Breakdown</h3>
                  <div className="grid grid-cols-1 gap-4">
                    {result.data.medications?.map((med, idx) => (
                      <div 
                        key={idx}
                        onMouseEnter={() => setHoveredMed(idx)}
                        onMouseLeave={() => setHoveredMed(null)}
                        className={`
                          relative p-6 rounded-3xl border transition-all duration-300
                          ${hoveredMed === idx 
                            ? 'bg-cyan-500/10 border-cyan-500/40 shadow-[0_0_30px_rgba(34,211,238,0.1)] -translate-x-2' 
                            : 'bg-white/5 border-white/5'}
                        `}
                      >
                         <div className="flex justify-between items-start mb-4">
                            <div>
                               <h4 className="text-2xl font-serif text-white mb-1">{med.name}</h4>
                               <div className="flex gap-2 text-[10px] font-bold text-cyan-400/70 uppercase">
                                 <span>{med.dosage}</span>
                                 <span className="text-white/10">•</span>
                                 <span>{med.frequency}</span>
                               </div>
                            </div>
                            <span className={`text-[9px] font-black px-2 py-0.5 rounded border ${
                              med.confidence === 'High' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/20' : 'bg-amber-500/20 text-amber-400 border-amber-500/20'
                            }`}>
                              {med.confidence} CONF.
                            </span>
                         </div>

                         <div className="grid grid-cols-2 gap-4 mb-4">
                            <div className="bg-black/20 p-3 rounded-xl border border-white/5">
                               <p className="text-[9px] text-white/30 uppercase tracking-widest mb-1">Frequency</p>
                               <p className="text-sm text-cyan-200">{med.frequency}</p>
                            </div>
                            <div className="bg-black/20 p-3 rounded-xl border border-white/5">
                               <p className="text-[9px] text-white/30 uppercase tracking-widest mb-1">Duration</p>
                               <p className="text-sm text-cyan-200">{med.duration}</p>
                            </div>
                         </div>

                         <p className="text-sm text-white/70 leading-relaxed border-t border-white/10 pt-4 font-light">
                            <strong className="text-[10px] text-cyan-500 uppercase block mb-1">Instruction</strong>
                            {med.instructions}
                         </p>
                      </div>
                    ))}
                  </div>
               </section>

               {/* 3. Safety & Reassurance */}
               <section className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="p-6 rounded-3xl bg-amber-500/5 border border-amber-500/10">
                     <h4 className="text-[10px] font-bold text-amber-500 uppercase tracking-widest mb-4 flex items-center gap-2">
                        <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                        Safety Protocol
                     </h4>
                     <p className="text-sm text-amber-200/80 leading-relaxed">
                        {result.data.safetyAdvice}
                     </p>
                     {result.data.verificationRequired && (
                        <div className="mt-4 p-3 bg-red-500/10 rounded-xl border border-red-500/20 text-[10px] text-red-200 font-bold uppercase tracking-wider text-center">
                           Pharmacist Verification Mandatory
                        </div>
                     )}
                  </div>

                  <div className="p-6 rounded-3xl bg-cyan-500/5 border border-cyan-500/10 flex flex-col justify-center">
                     <p className="text-lg font-serif italic text-white/80 text-center leading-relaxed">
                        "{result.data.reassuranceLine}"
                     </p>
                  </div>
               </section>

               {/* Ambiguity Warnings */}
               {result.data.ambiguityFlags && result.data.ambiguityFlags.length > 0 && (
                 <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-2xl">
                    <h4 className="text-[10px] font-bold text-red-400 uppercase mb-2">Ambiguities Detected</h4>
                    <ul className="text-xs text-red-200/70 space-y-1 pl-4 list-disc">
                       {result.data.ambiguityFlags.map((f, i) => <li key={i}>{f}</li>)}
                    </ul>
                 </div>
               )}

            </div>
          )}

        </div>

      </div>

      <style>{`
        @keyframes scan {
          0% { top: 0; }
          50% { top: 100%; }
          100% { top: 0; }
        }
      `}</style>
    </div>
  );
};

export default ClearScriptModule;

