                  >
                    {loading ? 'Analyzing' : 'Begin Analysis'}
                  </button>
               </div>
            </div>
          </div>

          {error && (
            <p className="text-center text-red-400 text-sm mt-4 animate-fade-in">{error}</p>
          )}
