        {/* --- RESULT SECTION (Grows Dynamically) --- */}
        {hasResult && result && (
           <div className="w-full mt-12 animate-slide-up space-y-8 pb-12">

             {/* 1. Emotional Mirror (Reassurance) */}
             <div className="text-center space-y-2">
